  const stages = [["Applied",86],["Screening",54],["Technical",31],["Manager Interview",18],["HR Interview",12],["Offer",8],["Joined",6]];
  const jobs = [
    {title:"Senior Platform Engineer",code:"REQ-2481",dept:"Engineering",manager:"Riya Kapoor",priority:"Critical",applicants:42,days:18,location:"Bengaluru",status:"Interviewing",fill:"72%"},
    {title:"Product Designer",code:"REQ-2490",dept:"Product",manager:"Ananya Rao",priority:"High",applicants:28,days:12,location:"Remote",status:"Screening",fill:"48%"},
    {title:"People Partner",code:"REQ-2494",dept:"People Operations",manager:"Nisha Singh",priority:"High",applicants:19,days:9,location:"Hyderabad",status:"Manager review",fill:"36%"},
    {title:"Data Analyst",code:"REQ-2502",dept:"Operations",manager:"Vikram Rao",priority:"Medium",applicants:23,days:6,location:"Bengaluru",status:"Open",fill:"21%"},
    {title:"Account Executive",code:"REQ-2506",dept:"Sales",manager:"Sameer Ali",priority:"Medium",applicants:17,days:4,location:"Mumbai",status:"Open",fill:"14%"}
  ];
